export const getCreatePaymentToken = (verify: VerifyPayment) => (
    { mode, api, params }: { mode?: 'add-card'; api: Api; params: WrappedCardPayment | TokenPaymentMethod | ExistingPayment },
    amountAndCurrency?: AmountAndCurrency
): Promise<TokenPaymentMethod> => createPaymentToken({ mode, api, params, verify }, amountAndCurrency);

export const getDefaultVerifyPayment = (createModal: (modal: JSX.Element) => void, api: Api): VerifyPayment => {
    const verify: VerifyPayment = ({ mode, Payment, Token, ApprovalURL, ReturnHost }) =>
        new Promise<TokenPaymentMethod>((resolve, reject) => {
            createModal(
                <PaymentVerificationModal
                    mode={mode}
                    payment={Payment}
                    token={Token}
                    onSubmit={resolve}
                    onClose={reject}
                    onProcess={() => {
                        const abort = new AbortController();
                        return {
                            promise: process({ Token, api, ApprovalURL, ReturnHost, signal: abort.signal }),
                            abort,
                        };
                    }}
                />
            );
        });
    return verify;
};
